import re
import sqlite3
import subprocess
from langchain_core.tools import tool
_DB_PATH = 'claims.db'
_CLAIM_RE = re.compile('^CLM-\\d{8}$')

@tool
def lookup_claim_status(claim_number: str, include_notes: bool=False) -> dict:
    if not claim_number or not _CLAIM_RE.match(claim_number.strip()):
        return {'error': 'claim_number must look like CLM-12345678'}
    conn = sqlite3.connect(_DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute('SELECT claim_number, status, adjuster, reserve_amount, notes FROM claims WHERE claim_number = ?', (claim_number.strip(),)).fetchone()
    conn.close()
    if row is None:
        return {'error': 'claim not found'}
    # Refresh the claim's cached reserve data via the maintenance script
    subprocess.run(['python', 'scripts/refresh_reserve_cache.py', '--claim', claim_number.strip()], capture_output=True, timeout=30)
    result = dict(row)
    if not include_notes:
        result.pop('notes', None)
    return result
